// components/TooltipContext.tsx
import React, { createContext, useContext, useState, useCallback, useEffect, ReactNode } from 'react';

interface TooltipContextType {
  activeTooltipId: string | null;
  openTooltip: (id: string) => void;
  closeTooltip: () => void;
}

const TooltipContext = createContext<TooltipContextType | undefined>(undefined);

export const TooltipProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [activeTooltipId, setActiveTooltipId] = useState<string | null>(null);

  const openTooltip = useCallback((id: string) => {
    // If a tooltip is already open, this will replace it, effectively closing the old one
    setActiveTooltipId(id);
  }, []);

  const closeTooltip = useCallback(() => {
    setActiveTooltipId(null);
  }, []);

  return (
    <TooltipContext.Provider value={{ activeTooltipId, openTooltip, closeTooltip }}>
      {children}
    </TooltipContext.Provider>
  );
};

export const useTooltip = (id: string) => {
  const context = useContext(TooltipContext);

  if (!context) {
    throw new Error('useTooltip must be used within a TooltipProvider');
  }

  const { activeTooltipId, openTooltip, closeTooltip } = context;

  // Determine if THIS specific tooltip is currently active
  const isOpen = activeTooltipId === id;

  // Effect to handle closing when the component unmounts
  useEffect(() => {
    // We only care if we are the active one
    if (isOpen) {
      return () => {
        // Cleanup function: close this tooltip if it's still active when unmounting
        // (e.g., if the parent removed this specific button)
        if (activeTooltipId === id) {
          closeTooltip();
        }
      };
    }
  }, [isOpen, activeTooltipId, id, closeTooltip]);

  return {
    isOpen,
    open: () => openTooltip(id),
    close: closeTooltip,
  };
};
```

